mapper.select:
/*selectMasterMpIfDivsnPopList*/ SELECT A.LEGACY_PO_NO , A.LEGACY_PO_SEQ , A.BUYER_ITEM_NO , B.DESCRIPTION_LOC , B.SPECIFICATION , A.ITEM_QTY , B.UNIT_MEASURE , B.MAKER_NAME , A.REMARK, A.PURCHASER_USER_DEPT, A.BYIT_COMORG_CODE, (SELECT BYCA_COMORG_LEVEL FROM ICOMCMPY WHERE COM_CODE = A.BUYER) AS COMORG_LEVEL, A.REF_IF_NO, A.ADD_DATE, A.RD_DATE, A.UNIT_PRICE FROM IF_PODT A , ICOMBYIT B WHERE A.STATUS <> 'D' AND A.BUYER = B.BUYER(+) AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO(+) AND B.STATUS(+) <> 'D'
AND A.BUYER = #{buyer}
AND A.LEGACY_PO_NO = #{legacy_po_no}
AND A.LEGACY_PO_SEQ = #{legacy_po_seq}
AND A.BUYER_ITEM_NO = #{buyer_item_no}

SELECT NVL(C.AGENT_SEQ,1) AS AGENT_SEQ , NVL(C.ITEM_QTY,0) AS ITEM_QTY, NVL(C.UNIT_PRICE,0) AS TARGET_PRICE, NVL(C.ITEM_QTY * C.UNIT_PRICE,0) AS ITEM_AMT, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = C.AGENT) AS AGENT_NAME, A.BUYER, A.LEGACY_PO_NO, A.LEGACY_PO_SEQ, A.BUYER_ITEM_NO, C.AGENT, C.CONTRACT_NO, C.CONTRACT_SEQ, 'UPDATE' AS STATUS, DECODE(D.PROCESS_TYPE,0,'직납',1,'재고','2','T/R','3','VMI','확인') AS PROCESS_TYPE, D.ORIGIN_AGENT, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = D.ORIGIN_AGENT) AS ORIGIN_AGENT_NAME, D.PROCESS_TYPE FROM IF_PODT A , POIFLOAD_DAEW C, ICOMCQDT D WHERE A.STATUS <> 'D' AND D.STATUS <> 'D' AND A.LEGACY_PO_NO = C.LEGACY_PO_NO AND A.LEGACY_PO_SEQ = C.LEGACY_PO_SEQ AND A.BUYER = C.COM_CODE AND C.COM_CODE = D.BUYER AND C.BUYER_ITEM_NO = D.BUYER_ITEM_NO AND C.CONTRACT_NO = D.CONTRACT_NO AND C.CONTRACT_SEQ = D.CONTRACT_SEQ
AND A.BUYER = #{buyer}
AND A.LEGACY_PO_NO = #{legacy_po_no}
AND A.LEGACY_PO_SEQ = #{legacy_po_seq}
AND A.BUYER_ITEM_NO = #{buyer_item_no}
ORDER BY C.AGENT_SEQ

mapper.update:

UPDATE  POIFLOAD_DAEW  SET
	ITEM_QTY        =  #{ITEM_QTY},
	AGENT           =  #{AGENT},
	CONTRACT_NO     =  #{CONTRACT_NO},
	CONTRACT_SEQ    =  #{CONTRACT_SEQ},
	CHANGE_USER_ID  =  #{st_user_id},
	UNIT_PRICE      =  #{TARGET_PRICE},
	CHANGE_DATE     =  TO_CHAR(SYSDATE,'YYYYMMDD'),
	CHANGE_TIME     =  TO_CHAR(SYSDATE,'HH24MISS')
WHERE COM_CODE		=  #{BUYER}
AND LEGACY_PO_NO	=  #{legacy_po_no}
AND LEGACY_PO_SEQ	=  #{legacy_po_seq}
AND AGENT_SEQ		=  #{AGENT_SEQ}


DELETE POIFLOAD_DAEW
WHERE COM_CODE		= #{BUYER}
AND LEGACY_PO_NO	= #{legacy_po_no}
AND LEGACY_PO_SEQ	= #{legacy_po_seq}
AND AGENT_SEQ		= #{AGENT_SEQ}
